const fs=require('node:fs'),vm=require('node:vm');const ctx=vm.createContext({});vm.runInContext(fs.readFileSync(__dirname+'/index.html','utf8').match(/<script id="motion-core">([\s\S]*?)<\/script>/)[1],ctx);let paths='';for(let k=0;k<28;k++){let d='';for(let j=0;j<=300;j++){let [x,y]=ctx.PhaseGarden.point(j*Math.PI*2/300,k,6,.8);d+=(j?' L':'M')+(600+x*440).toFixed(2)+' '+(410+y*440).toFixed(2)}paths+=`<path d="${d}" fill="none" stroke="${k%3===0?'#bedaa0':'#ebae5d'}" stroke-opacity=".55" stroke-width="1.2"/>`;}fs.writeFileSync(__dirname+'/poster.svg',`<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="800" viewBox="0 0 1200 800" role="img" aria-label="相位花园固定于第六秒的原创参数轨道"><rect width="1200" height="800" fill="#101c1b"/><g fill="none" stroke="#293c31"><circle cx="600" cy="410" r="360"/><circle cx="600" cy="410" r="240"/><path d="M100 410H1100M600 80V740" stroke-dasharray="2 10"/></g>${paths}<g font-family="sans-serif"><text x="55" y="65" fill="#bfd5ad" font-size="15" letter-spacing="3">CODING MOTION / ORIGINAL STUDY 001</text><text x="55" y="725" fill="#ecebdd" font-size="35" letter-spacing="5">相位花园</text><text x="55" y="762" fill="#ecbc71" font-size="16" letter-spacing="3">PHASE GARDEN</text><text x="940" y="752" fill="#a0b29d" font-size="15">T = 06.00 S</text></g></svg>`);
